package com.nexamart.backend.repository;import com.nexamart.backend.domain.Category;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.util.*;public interface CategoryRepository extends JpaRepository<Category,Long>{Optional<Category> findByNameIgnoreCase(String name);@Query("select c from Category c where (:q is null or lower(c.name) like lower(concat('%',:q,'%'))) and (:active is null or c.active=:active)")Page<Category> search(@Param("q")String q,@Param("active")Boolean active,Pageable p);}
